package nl.smartstreamlabs.sbwdroneconfig;
import java.util.*;import net.minecraft.core.*;import net.minecraft.nbt.CompoundTag;import net.minecraft.network.chat.Component;import net.minecraft.network.protocol.game.ClientboundBlockEntityDataPacket;import net.minecraft.server.level.*;import net.minecraft.world.*;import net.minecraft.world.entity.player.*;import net.minecraft.world.inventory.AbstractContainerMenu;import net.minecraft.world.item.ItemStack;import net.minecraft.world.level.*;import net.minecraft.world.level.block.entity.*;import net.minecraft.world.level.block.state.BlockState;import net.minecraft.world.phys.*;
/** One cargo owner and journalled UUID handoff, using the existing mission transaction and tickets. */
public class Fl01PlatformBlockEntity extends BlockEntity implements MenuProvider,MissionPlatform{
 public enum Phase{EMPTY,RAISING,READY,RESETTING,RECOVERING}
 private ItemStack cargo=ItemStack.EMPTY;private final MissionDraft draft=new MissionDraft();private UUID owner,load,actor,launch;private Phase phase=Phase.EMPTY;private long start;private boolean networkRead,recoverClock;private int failure;private int handoff=-1;private UUID handoffId;private long handedAt;private ItemStack visual=ItemStack.EMPTY;private long nextCheck;private boolean clear,manualLaunch;
 public Fl01PlatformBlockEntity(BlockPos p,BlockState s){super(AddonBlockEntities.FL_LP.get(),p,s);draft.enabled=true;}
 public Direction facing(){return getBlockState().getValue(Fl01PlatformBlock.FACING);}public MissionDraft mission(){return draft;}public String missionKind(){return "flamingo";}public ItemStack drone(){return cargo;}public UUID loadedId(){return cargo.isEmpty()?null:load;}public boolean missionEditable(){return phase==Phase.EMPTY||phase==Phase.READY;}public void missionSync(){sync();}public Vec3 missionMount(){return Fl01Geometry.point(Fl01Geometry.dock(worldPosition,facing(),3.5),Vec3.ZERO);}
 public void requestManualLaunch(Player p){if(p instanceof ServerPlayer sp&&PlatformMonitor.ready(sp,loadedId()))requestLaunch(p,true);}
 public boolean canUse(Player p){return !isRemoved()&&level!=null&&!level.isClientSide&&p.level()==level&&p.isAlive()&&Fl01Geometry.transform(Fl01Geometry.world(worldPosition,facing()),Fl01Geometry.PLATFORM.bounds).distanceToSqr(p.position())<=64&&(owner==null||owner.equals(p.getUUID())||p.hasPermissions(2))&&level.mayInteract(p,worldPosition)&&p.mayUseItemAt(worldPosition,Direction.UP,p.getMainHandItem());}
 public void placed(Player p){owner=p.getUUID();sync();}public int fuel(){return cargo.isEmpty()?0:Fl01Item.fuel(cargo);}public Phase phase(){return phase;}
 public double animation(float partial){if(level==null)return 0;double t=Math.max(0,level.getGameTime()-start+partial);return phase==Phase.RAISING?Math.min(3.5,t/20):phase==Phase.RESETTING?Math.min(6,3.5+t/20):0;}
 public ItemStack preview(){if(handoff>=0&&level!=null){var e=level.getEntity(handoff);if(e!=null&&e.getUUID().equals(handoffId))return ItemStack.EMPTY;if(level.getGameTime()-handedAt<=6)return visual;}return cargo;}
 public double handoffTravel(float p){return handoff>=0&&level!=null?Math.max(0,Math.min(6,level.getGameTime()-handedAt+p)):0;}
 public double previewTime(float p){return handoff>=0&&level!=null&&level.getGameTime()-handedAt<=6?3.5:animation(p);}
 public static String reasonKey(int r){return "fl01.reason."+r;}private void fail(Player p,int r){failure=r;p.displayClientMessage(Component.translatable(reasonKey(r)),true);sync();}
 public int displayReason(Player p){return launchReason(p,false);}
 private int launchReason(Player p,boolean manual){if(!canUse(p))return 6;if(cargo.isEmpty())return 1;if(PlatformInventory.editing(this))return 2;if(phase!=Phase.READY)return 2;if(fuel()<=0)return 3;if(!manual&&(!draft.enabled||!draft.valid))return 9;if(level.getGameTime()>=nextCheck){clear=exitClear();nextCheck=level.getGameTime()+20;}return clear?0:4;}
 public void loadDrone(Player p,ItemStack s){if(PlatformInventory.guard(this,p))return;if(!(level instanceof ServerLevel)||!canUse(p)){fail(p,6);return;}if(!s.is(AddonItems.FL01.get())){fail(p,10);return;}if(!cargo.isEmpty()||phase!=Phase.EMPTY){fail(p,2);return;}if(!loadedClear(false)){fail(p,4);return;}cargo=s.copy();cargo.setCount(1);load=UUID.randomUUID();handoff=-1;handoffId=null;visual=ItemStack.EMPTY;actor=null;launch=null;failure=0;if(!p.getAbilities().instabuild)s.shrink(1);phase=Phase.READY;sync();}
 public void loadInventory(Player p){if(!canUse(p))return;for(var s:p.getInventory().items)if(s.is(AddonItems.FL01.get())){loadDrone(p,s);return;}fail(p,10);}
 public void variant(Player p){if(PlatformInventory.guard(this,p))return;if(!canUse(p)||phase!=Phase.READY||cargo.isEmpty())return;var n=Fl01Item.data(cargo);n.putBoolean("Pink",!n.getBoolean("Pink"));Fl01Item.data(cargo,n);sync();}
 public void requestReturn(Player p){if(PlatformInventory.guard(this,p))return;if(!canUse(p)){fail(p,6);return;}if(cargo.isEmpty()){fail(p,1);return;}if(phase!=Phase.READY){fail(p,2);return;}var returned=cargo.copy();if(!PlatformInventory.canReceive(p,returned)||!p.getInventory().add(returned)){fail(p,8);return;}cargo=ItemStack.EMPTY;load=null;phase=Phase.EMPTY;failure=0;sync();}
 public void refuel(Player p,InteractionHand h){if(PlatformInventory.guard(this,p))return;if(!canUse(p)||phase!=Phase.READY||cargo.isEmpty())return;var held=p.getItemInHand(h);if(!held.is(AddonItems.GASOLINE_JERRYCAN.get())||fuel()>=Fl01Config.FUEL.get())return;var n=Fl01Item.data(cargo);n.putInt("Fuel",Fl01Config.FUEL.get());Fl01Item.data(cargo,n);if(!p.getAbilities().instabuild){held.shrink(1);var empty=new ItemStack(AddonItems.EMPTY_JERRYCAN.get());if(!p.getInventory().add(empty))p.drop(empty,false);}sync();}
 public void requestLaunch(Player p){requestLaunch(p,false);}
 private void requestLaunch(Player p,boolean manual){if(PlatformInventory.guard(this,p))return;if(!canUse(p)){fail(p,6);return;}int why=launchReason(p,manual);if(why!=0){fail(p,why);return;}if(manual&&(!(p instanceof ServerPlayer sp)||!PlatformMonitor.ready(sp,load))){fail(p,6);return;}if(!manual){if(!missionValid(p))return;if(missionMount().distanceTo(draft.target)>Fl01Config.RANGE.get()){draft.message="Target exceeds FL-01 range";fail(p,9);return;}if(!MissionManager.get(((ServerLevel)level).getServer()).reserve(this,p,load))return;}manualLaunch=manual;actor=p.getUUID();launch=load;failure=0;phase=Phase.RAISING;start=level.getGameTime();sync();}
 public void cancel(Player p){if(PlatformInventory.guard(this,p))return;if(!canUse(p)||phase!=Phase.RAISING)return;MissionManager.get(((ServerLevel)level).getServer()).abortPreparation(launch);launch=null;actor=null;phase=Phase.RESETTING;start=level.getGameTime();sync();}
 public AABB loadedEnvelope(){AABB all=null;for(double t:new double[]{0,1.5,3.5}){var b=Fl01Geometry.transform(Fl01Geometry.dock(worldPosition,facing(),t),Fl01Geometry.MISSILE.bounds);all=all==null?b:all.minmax(b);}return all;}
 private boolean loadedClear(boolean entities){for(double time:new double[]{0,1.5,3.5})if(!poseClear(Fl01Geometry.dock(worldPosition,facing(),time),entities))return false;return true;}
 public boolean exitClear(){if(!loadedClear(true))return false;var direction=Vec3.directionFromRotation(-35,facing().toYRot());for(int step=1;step<=10;step++){var frame=Fl01Geometry.dock(worldPosition,facing(),3.5);frame.m30(frame.m30()+direction.x*step*.5);frame.m31(frame.m31()+direction.y*step*.5);frame.m32(frame.m32()+direction.z*step*.5);if(!poseClear(frame,true))return false;}return true;}
 /** Collision uses the same oriented fuselage/wing/engine volumes as the flying FL-01.
  * Empty space below the wings and in the union of launch poses is not an obstruction. */
 private boolean poseClear(org.joml.Matrix4d frame,boolean entities){if(level==null)return false;
  for(var part:Fl01Geometry.AIRFRAME){var area=Fl01Geometry.transform(frame,Fl01Geometry.partBounds(part));if(area.minY<level.getMinBuildHeight()||area.maxY>=level.getMaxBuildHeight()||!level.getWorldBorder().isWithinBounds(area))return false;var lo=BlockPos.containing(area.minX,area.minY,area.minZ);var hi=BlockPos.containing(area.maxX,area.maxY,area.maxZ);if(!level.hasChunksAt(lo,hi))return false;var box=Fl01Geometry.partBox(frame,part);
   for(var pos:BlockPos.betweenClosed(lo,hi)){var state=level.getBlockState(pos);if(state.getBlock()instanceof Fl01PlatformBlock&&Fl01PlatformBlock.root(pos,state).equals(worldPosition))continue;for(var collision:state.getCollisionShape(level,pos).toAabbs())if(com.atsuishio.superbwarfare.tools.OBB.isColliding(box,collision.move(pos)))return false;}
   if(entities)for(var entity:level.getEntities((net.minecraft.world.entity.Entity)null,area,e->e.isAlive()&&!e.isSpectator()&&e.isPickable()&&!(e instanceof net.minecraft.world.entity.item.ItemEntity)))if(com.atsuishio.superbwarfare.tools.OBB.isColliding(box,entity.getBoundingBox()))return false;
  }return true;
 }
 public static void tick(Level l,BlockPos p,BlockState s,Fl01PlatformBlockEntity b){b.tick();}
 private void tick(){if(level.getGameTime()%20==0)missionRefresh();if(phase==Phase.RECOVERING){if(!recoverClock){recoverClock=true;return;}if(launch!=null&&(((ServerLevel)level).getEntity(launch)!=null||MissionManager.wasSpawned((ServerLevel)level,launch)))cargo=ItemStack.EMPTY;MissionManager.get(((ServerLevel)level).getServer()).abortPreparation(launch);launch=null;actor=null;phase=cargo.isEmpty()?Phase.EMPTY:Phase.READY;sync();return;}if(phase==Phase.RESETTING){if(level.getGameTime()-start>=50){phase=cargo.isEmpty()?Phase.EMPTY:Phase.READY;sync();}return;}if(phase!=Phase.RAISING||level.getGameTime()-start<70)return;var p=actor==null?null:level.getPlayerByUUID(actor);if(p==null||!canUse(p)||cargo.isEmpty()||!Objects.equals(load,launch)||fuel()<=0||manualLaunch&&(!(p instanceof ServerPlayer sp)||!PlatformMonitor.ready(sp,load))||!manualLaunch&&!missionValid(p)||!exitClear()){if(p!=null)fail(p,4);MissionManager.get(((ServerLevel)level).getServer()).abortPreparation(launch);launch=null;actor=null;phase=Phase.RESETTING;start=level.getGameTime();sync();return;}var manager=MissionManager.get(((ServerLevel)level).getServer());if(!manualLaunch&&!manager.prepared(launch)){var f=manager.find(launch);if(f==null||!f.active())cancel(p);return;}var e=createDrone();if(e==null){cancel(p);fail(p,7);return;}e.launch(this,p,launch,manualLaunch);if(!manualLaunch&&!manager.bind(launch,e)){cancel(p);fail(p,7);return;}handoff=e.getId();handoffId=e.getUUID();handedAt=level.getGameTime();visual=cargo.copy();sync();if(!((ServerLevel)level).addFreshEntity(e)){MissionManager.spawnRejected(e);handoff=-1;visual=ItemStack.EMPTY;cancel(p);fail(p,7);return;}if(manualLaunch)PlatformMonitor.activate((ServerPlayer)p,e);cargo=ItemStack.EMPTY;load=null;launch=null;actor=null;phase=Phase.RESETTING;start=level.getGameTime();level.playSound(null,worldPosition,net.minecraft.core.registries.BuiltInRegistries.SOUND_EVENT.get(net.minecraft.resources.ResourceLocation.tryParse("superbwarfare:small_rocket_fire_3p")),net.minecraft.sounds.SoundSource.BLOCKS,1,.65f);sync();}
 Fl01Entity createDrone(){
    if(cargo.isEmpty()||level==null)return null;var d=(Fl01Entity)PlatformInventory.hydrate(AddonEntities.FL01.get().create(level),PlatformInventory.saved(cargo));
    if(d!=null){if(!PlatformInventory.saved(cargo).contains("Health",99))d.setHealth(18);var n=new CompoundTag();d.saveWithoutId(n);n.putInt("FlFuel",fuel());n.putBoolean("FlPink",Fl01Item.pink(cargo));if(n.contains("Item",10)&&n.getCompound("Item").isEmpty())n.remove("Item");d.load(n);}return d;
 }
 @Override public void setRemoved(){PlatformInventory.closeFor(this);super.setRemoved();}
 public void dropContents(){PlatformInventory.closeFor(this);if(level instanceof ServerLevel sl){boolean consumed=launch!=null&&(sl.getEntity(launch)!=null||MissionManager.wasSpawned(sl,launch));if(!cargo.isEmpty()&&!consumed)net.minecraft.world.Containers.dropItemStack(level,worldPosition.getX()+.5,worldPosition.getY()+1,worldPosition.getZ()+.5,cargo);cargo=ItemStack.EMPTY;MissionManager.get(sl.getServer()).abortPreparation(launch);launch=null;actor=null;load=null;sync();}}
 private void sync(){setChanged();if(level!=null&&!level.isClientSide)level.sendBlockUpdated(worldPosition,getBlockState(),getBlockState(),3);nextCheck=0;}
 private void write(CompoundTag n,net.minecraft.core.HolderLookup.Provider registries){if(!cargo.isEmpty())n.put("Cargo",cargo.save(registries));n.put("Mission",draft.write());n.putInt("Phase",phase.ordinal());n.putLong("Start",start);n.putInt("Failure",failure);if(owner!=null)n.putUUID("Owner",owner);if(load!=null)n.putUUID("Load",load);if(actor!=null)n.putUUID("Actor",actor);if(launch!=null)n.putUUID("Launch",launch);n.putInt("Handoff",handoff);if(handoffId!=null)n.putUUID("HandoffId",handoffId);n.putLong("HandedAt",handedAt);}
 @Override protected void saveAdditional(CompoundTag n,net.minecraft.core.HolderLookup.Provider registries){super.saveAdditional(n,registries);write(n,registries);}
 @Override protected void loadAdditional(CompoundTag n,net.minecraft.core.HolderLookup.Provider registries){super.loadAdditional(n,registries);if(!cargo.isEmpty())visual=cargo.copy();cargo=ItemStack.parseOptional(registries,n.getCompound("Cargo"));draft.read(n.getCompound("Mission"));phase=Phase.values()[Math.max(0,Math.min(Phase.values().length-1,n.getInt("Phase")))];start=n.getLong("Start");failure=n.getInt("Failure");owner=n.hasUUID("Owner")?n.getUUID("Owner"):null;load=n.hasUUID("Load")?n.getUUID("Load"):null;actor=n.hasUUID("Actor")?n.getUUID("Actor"):null;launch=n.hasUUID("Launch")?n.getUUID("Launch"):null;handoff=n.contains("Handoff")?n.getInt("Handoff"):-1;handoffId=n.hasUUID("HandoffId")?n.getUUID("HandoffId"):null;handedAt=n.getLong("HandedAt");if(!cargo.isEmpty())visual=cargo.copy();if(!networkRead){manualLaunch=false;phase=Phase.RECOVERING;recoverClock=false;handoff=-1;visual=ItemStack.EMPTY;}}
 @Override public CompoundTag getUpdateTag(net.minecraft.core.HolderLookup.Provider registries){var n=new CompoundTag();write(n,registries);return n;}@Override public ClientboundBlockEntityDataPacket getUpdatePacket(){return ClientboundBlockEntityDataPacket.create(this);}@Override public void handleUpdateTag(CompoundTag n,net.minecraft.core.HolderLookup.Provider registries){networkRead=true;try{loadAdditional(n,registries);}finally{networkRead=false;}}@Override public void onDataPacket(net.minecraft.network.Connection c,ClientboundBlockEntityDataPacket p,net.minecraft.core.HolderLookup.Provider registries){handleUpdateTag(p.getTag(),registries);}
 @Override public Component getDisplayName(){return Component.literal("FL-LP • Flamingo Launch Platform");}@Override public AbstractContainerMenu createMenu(int id,Inventory i,Player p){return new Fl01Menu(id,i,this);}public void open(ServerPlayer p){if(canUse(p))p.openMenu(this,buffer->buffer.writeBlockPos(worldPosition));else fail(p,6);}public AABB getRenderBoundingBox(){return new AABB(worldPosition).inflate(14);}
}
